import { Component } from '@angular/core';

// ❌ OLD: Permission logic is copy-pasted into every template that
// needs it. If the permission model changes, every usage must change.
@Component({
  selector: 'app-root',
  template: `
    @if (auth.can('admin')) { <admin-panel /> } <!-- ❌ OLD: repeated -->
    @if (auth.can('admin')) { <admin-link /> }  <!-- ❌ OLD: and again -->
    @if (auth.can('editor')) { <editor-tools /> } <!-- ❌ OLD: custom per use -->
  `,
})
export class AppComponent {
  constructor(public auth: AuthService) {}
}

import { Directive, Input, TemplateRef, ViewContainerRef } from '@angular/core';

// ✅ NEW: A reusable structural directive. The * syntax expands to an
// <ng-template>; the directive uses TemplateRef + ViewContainerRef to
// create or clear the embedded view based on the condition.
@Directive({ selector: '[hasPermission]' })
export class HasPermissionDirective {
  private condition = false;

  constructor(
    private tpl: TemplateRef<unknown>, // ✅ NEW: the ng-template content
    private vcr: ViewContainerRef, // ✅ NEW: the anchor for the view
  ) {}

  @Input() set hasPermission(perm: string) {
    this.condition = inject(AuthService).can(perm);
    this.update();
  }

  private update() {
    this.vcr.clear(); // ✅ NEW: remove any existing view
    if (this.condition) {
      this.vcr.createEmbeddedView(this.tpl); // ✅ NEW: render the template
    }
  }
}

// Usage: <div *hasPermission="'admin'"><admin-panel /></div>
// The compiler expands this to:
// <ng-template hasPermission="'admin'"><admin-panel /></ng-template>
